$('map').addEventListener('pointerup',endDrag);$('map').addEventListener('pointercancel',endDrag);$('map').addEventListener('lostpointercapture',endDrag);$('map').addEventListener('wheel',e=>{e.preventDefault();zoom=clamp(zoom*(e.deltaY<0?1.1:.9),1,4);if(zoom===1)center={x:500,y:312.5};draw();},{passive:false});$('map').ondragover=e=>e.preventDefault();$('map').ondrop=e=>{e.preventDefault();let p=pointer(e);addUnit(e.dataTransfer.getData('text/plain'),p.x,p.y);};
