$('project-file').onchange=async e=>{let f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>128*1024*1024)return tell('128MB以下のファイルを選択してください。');try{let raw=JSON.parse(await f.text()),replay=raw.format==='mfdco-replay'?validateReplay(raw):null,p=replay?replay.project:validate(raw);confirmReplace(replay?'固定リプレイを開く':'プロジェクトを読み込む',()=>{clearTimeout(saveTimer);checkpoint();project=p;restoreChanged();if(replay){clearTimeout(saveTimer);readonlyReplay=replay;applyReplayView(replay.view);requestFrame(0);tell('固定リプレイを読み込みました。再計算せずに再生します。');}else tell('プロジェクトを読み込みました。');});}catch(err){tell('読み込みできません：'+err.message);}};
