$('background-file').onchange=async e=>{let f=e.target.files[0];e.target.value='';if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>8*1024*1024)return tell('8MB以下のPNG・JPEG・WebPを選んでください。');try{let bitmap=await createImageBitmap(f);if(bitmap.width>8192||bitmap.height>8192){bitmap.close();return tell('画像は縦横8192px以下にしてください。');}bitmap.close();let reader=new FileReader();reader.onload=()=>{edit(()=>{project.background=reader.result;project.backgroundBounds=null;backgroundView=reader.result;pixel=0;$('pixel').value='0';},{quiet:true});tell('背景を設定しました。地形判定はペイントデータを使用します。');};reader.readAsDataURL(f);}catch{tell('画像を読み込めませんでした。');}};
$('pixel').onchange=async()=>{pixel=Number($('pixel').value);if(!project.background){draw();if(pixel)tell('ピクセル化する背景画像を読み込んでください。');return;}if(!pixel){backgroundView=project.background;draw();return;}let img=new Image();img.onload=()=>{let c=document.createElement('canvas');c.width=pixel;c.height=clamp(Math.round(pixel*project.heightKm/project.widthKm),1,4096);let ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);backgroundView=c.toDataURL('image/png');draw();};img.src=project.background;};
