$('image-export').onclick=async()=>{if(['settings','help','mapedit'].includes(activeScreen))return tell('出力する戦況・管制画面へ切り替えてください。');if(activeScreen!=='tactical')return exportOperationsImage();if(pendingBattle||exportBusy)return tell('計算完了後に画像を保存してください。');playing=false;updateClock();try{const width=$('aspect').value==='square'?1080:1920,height=1080,c=document.createElement('canvas');c.width=width;c.height=height;await paintSvg(c,renderDocument(sceneContext(),{width,height,zoom,center}),new AbortController().signal);c.toBlob(blob=>{if(blob){download(basename()+'-frame'+frame+'.png',blob);tell('現在の表示をPNGで保存しました。');}else tell('画像の書き出しに失敗しました。');},'image/png');}catch(err){tell(err.message);}};
function defaultsEditor(){modal('兵科の既定値',`<p class="hint">変更は新しく追加する部隊に適用します。このプロジェクト内に保存されます。</p><div style="overflow:auto"><table class="settings-table"><thead><tr><th>兵科</th><th>速度 km/h</th><th>HP</th><th>攻撃力 / 秒</th><th>射程 km</th><th>攻撃対象</th></tr></thead><tbody>${project.defaults.map(t=>`<tr><td>${esc(t.name)}</td>${['speed','hp','attack','range'].map(k=>`<td><input type="number" step="any" min="${k==='speed'?.1:k==='hp'?1:0}" max="${k==='speed'?20000:k==='hp'?1000000:k==='attack'?100000:10000}" data-default="${t.id}" data-key="${k}" value="${t[k]}" aria-label="${esc(t.name)} ${k}"></td>`).join('')}<td>${[['land','陸'],['sea','海'],['air','空']].map(([d,n])=>`<label><input type="checkbox" data-default-domain="${t.id}" data-domain="${d}" ${t.targetDomains.includes(d)?'checked':''}>${n}</label>`).join('')}</td></tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button id="defaults-reset">初期値に戻す</button><button id="defaults-save" class="primary">適用</button></div>`);$('defaults-reset').onclick=()=>{document.querySelectorAll('[data-default]').forEach(el=>el.value=TYPES.find(t=>t.id===el.dataset.default)[el.dataset.key]);document.querySelectorAll('[data-default-domain]').forEach(el=>el.checked=unit('temp',el.dataset.defaultDomain,0,0).targetDomains.includes(el.dataset.domain));};$('defaults-save').onclick=()=>{let inputs=[...document.querySelectorAll('[data-default]')];if(inputs.some(el=>!el.checkValidity()||el.value===''))return tell('既定値の数値を確認してください。');edit(()=>{inputs.forEach(el=>project.defaults.find(t=>t.id===el.dataset.default)[el.dataset.key]=Number(el.value));project.defaults.forEach(t=>t.targetDomains=[...document.querySelectorAll('[data-default-domain]')].filter(el=>el.dataset.defaultDomain===t.id&&el.checked).map(el=>el.dataset.domain));},{quiet:true});$('modal').close();};};
