document.addEventListener('keydown',e=>{if(e.key==='Escape'&&recording){setRecording(false);return;}if($('modal').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();$('play').click();}if(e.key==='ArrowRight'){e.preventDefault();seek(frame+1);}if(e.key==='ArrowLeft'){e.preventDefault();seek(frame-1);}if(e.key==='Escape')setTool('select');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save();}});
