let last=performance.now(),accum=0;
function radarDraw(){$('radar-count').textContent=`${resolveRadars(project,project.units.map(u=>({id:u.id,...viewState(u)})),frame).filter(r=>r.enabled).length} / ${project.radars.length} 基稼働`;if(mode!=='radar')return;$('map').querySelectorAll('[data-unit]').forEach(g=>g.style.pointerEvents=g.getAttribute('opacity')==='0'?'none':'auto');}
$('radar-hide').onchange=draw;$('radar-trail').onchange=draw;
function loop(now){let dt=Math.min(1000,now-last);last=now;if(playing&&!pendingBattle){accum+=dt;let n=Math.floor(accum/(1000/rate));if(n){accum-=n*1000/rate;let target=clamp(frame+n,0,project.duration);if(target===project.duration)playing=false;requestFrame(target);updateClock();}}requestAnimationFrame(loop);}

function fitMap(){const stage=$('map-frame').parentElement,box=$('map-frame');if(window.innerHeight<480){box.style.width='';box.style.height='';return;}const style=getComputedStyle(stage),w=Math.max(1,stage.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight)),h=Math.max(1,stage.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom)),ratio=$('aspect').value==='square'?1:16/9;let width=Math.min(w,h*ratio);box.style.width=width+'px';box.style.height=width/ratio+'px';const physical=project.widthKm/project.heightKm,innerWidth=Math.min(width,width/ratio*physical);$('map').style.width=innerWidth+'px';$('map').style.height=innerWidth/physical+'px';$('map').setAttribute('preserveAspectRatio','none');}
if(typeof ResizeObserver!=='undefined')new ResizeObserver(fitMap).observe($('map-frame').parentElement);window.addEventListener('resize',fitMap);
