function captureView(){return{screen:activeScreen,consoleRadarId,consoleFilter,consolePage,facilityFilter:{...facilityFilter},linkedUnit:selected||'',mode,aspect:$('aspect').value,zoom,center:{...center},layers:{...layers},pixel,radarHide:$('radar-hide').checked,radarTrail:Number($('radar-trail').value)};}
function applyReplayView(v){facilityFilter={search:'',type:'all',team:'all',...v.facilityFilter};activeScreen=v.screen||'tactical';consoleRadarId=v.consoleRadarId||'';consoleFilter=v.consoleFilter||'all';consolePage=v.consolePage||0;if(project.units.some(u=>u.id===v.linkedUnit))selected=v.linkedUnit;switchScreen(activeScreen);mode=v.mode;zoom=v.zoom;center={...v.center};layers={...v.layers};$('aspect').value=v.aspect;$('aspect').onchange();$('mode-map').classList.toggle('active',mode==='map');$('mode-radar').classList.toggle('active',mode==='radar');$('radar-options').hidden=mode!=='radar';document.querySelectorAll('[data-layer]').forEach(el=>el.checked=layers[el.dataset.layer]);$('radar-hide').checked=v.radarHide;$('radar-trail').value=v.radarTrail;$('pixel').value=v.pixel;$('pixel').onchange();}
