function replayForVideo(end,view,signal,onProgress){
 if(readonlyReplay)return Promise.resolve(readonlyReplay);
 return new Promise((resolve,reject)=>{let worker=null,done=false;const finish=(error,value)=>{if(done)return;done=true;worker?.terminate();signal.removeEventListener('abort',cancel);error?reject(error):resolve(value);};const cancel=()=>finish(new DOMException('出力を中止しました。','AbortError'));
  try{abortIfNeeded(signal);worker=new Worker(new URL('./combat-worker.mjs',import.meta.url),{type:'module'});signal.addEventListener('abort',cancel,{once:true});worker.onmessage=e=>{const v=e.data;if(v.type==='progress'){onProgress(v.frame,v.target);return;}if(v.type==='exported'){try{finish(null,v.replay);}catch(err){finish(err);}}else finish(new Error(v.message||'動きの計算に失敗しました。'));};worker.onerror=()=>finish(new Error('動きの計算を開始できません。'));worker.postMessage({type:'video',id:1,project,end,view});}catch(err){finish(err);}
 });
}
async function exportBackground(view,signal){
 if(!project.background||!view.pixel)return project.background;
 const canvas=document.createElement('canvas');canvas.width=view.pixel;canvas.height=clamp(Math.round(view.pixel*project.heightKm/project.widthKm),1,4096);
 await paintSvg(canvas,`<svg xmlns="http://www.w3.org/2000/svg" width="${canvas.width}" height="${canvas.height}"><image href="${project.background}" width="100%" height="100%" preserveAspectRatio="none"/></svg>`,signal);return canvas.toDataURL('image/png');
}
$('video-export').onclick=()=>{if(['settings','help','mapedit'].includes(activeScreen))return tell('出力する戦況・管制画面へ切り替えてください。');
 if(pendingBattle||exportBusy)return tell('現在の計算完了をお待ちください。');if(project.units.length>80)return tell('映像出力は80部隊までです。');
 const webmAvailable=typeof VideoEncoder!=='undefined'&&typeof VideoFrame!=='undefined';
 modal('動画・PNG連番を書き出す',`<div class="export-grid"><label class="field">出力対象<select id="export-batch"><option value="current">現在の画面</option><option value="sync">地図・レーダー・武装・通信を同期出力</option><option value="cuts">保存したカットを一括出力</option></select></label><label class="field">形式<select id="export-format"><option value="webm" ${webmAvailable?'':'disabled'}>WebM動画 / 無音</option><option value="png" ${webmAvailable?'':'selected'}>PNG連番 / ZIP</option></select></label><label class="field">画面比率<select id="export-aspect"><option value="wide" ${$('aspect').value==='wide'?'selected':''}>16:9</option><option value="square" ${$('aspect').value==='square'?'selected':''}>1:1</option></select></label><label class="field">開始frame<input id="export-start" type="number" min="0" max="${Math.min(project.duration,10000)}" value="${exportCut?.from??0}"></label><label class="field">終了frame（含む）<input id="export-end" type="number" min="0" max="${Math.min(project.duration,10000)}" value="${exportCut?.to??Math.min(project.duration,1440)}"></label><label class="field">出力fps<select id="export-fps">${[1,5,10,15,24,30,60].map(n=>`<option ${n===30?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">解像度<select id="export-height"><option value="360">360p</option><option value="720" selected>720p</option><option value="1080">1080p</option></select></label></div><label class="check"><input type="checkbox" id="export-transparent">戦況図PNGの背景を透過（地形も非表示）</label><label class="check"><input type="checkbox" id="export-stamp" checked>日時・frameを映像に表示</label><p id="export-summary" class="export-summary"></p><p class="hint">1枚＝作中時間${project.secondsPerFrame}秒。現在の画面を出力します。戦況編集は表示レイヤーと拡大位置、CIC等は固定配置を使います。出力中も画面の録画は行いません。</p>${webmAvailable?'':'<p class="warn">この環境では動画出力が利用できません。PNG連番を利用できます。</p>'}<canvas id="export-canvas" class="export-preview" width="640" height="360" hidden></canvas><progress id="video-progress" max="100" value="0" hidden></progress><p id="video-message" class="hint" role="status"></p><div class="dialog-actions"><button id="video-cancel">閉じる</button><button id="video-start" class="primary">書き出す</button></div>`);
 const planFromForm=()=>exportPlan({start:Number($('export-start').value),end:Number($('export-end').value),fps:Number($('export-fps').value),height:Number($('export-height').value),aspect:$('export-aspect').value,format:$('export-format').value},project.duration);
 const summarize=()=>{try{const p=planFromForm();if(!$('export-start').value||!$('export-end').value)throw new Error('開始・終了frameを入力してください。');$('export-summary').textContent=`${p.count}枚 · ${p.width} × ${p.height} · ${p.fps}fps · ${p.duration.toFixed(2)}秒`;$('video-start').disabled=false;}catch(err){$('export-summary').textContent=err.message;$('video-start').disabled=true;}};
 document.querySelectorAll('.export-grid input,.export-grid select').forEach(el=>el.oninput=summarize);summarize();$('video-cancel').onclick=()=>{if(videoJob)videoJob.abort();else $('modal').close();};
 $('video-start').onclick=async()=>{
  let plan;try{plan=planFromForm();}catch(err){tell(err.message);return;}
  const batch=$('export-batch').value,transparent=$('export-transparent').checked;if(transparent&&plan.format!=='png')return tell('背景透過はPNG連番を選択してください。');let jobs;try{jobs=batch==='cuts'?project.cuts.map((c,i)=>({name:String(i+1).padStart(2,'0')+'-'+c.name,screen:c.screen,mode:c.mode,unitId:c.unitId,plan:exportPlan({...plan,start:c.from,end:c.to},project.duration)})):batch==='sync'?[['map','tactical'],['radar','tactical'],[mode,'weapons'],[mode,'comms']].map(([m,screen],i)=>({name:String(i+1)+'-'+screen,screen,mode:m,unitId:selected,plan})):[{name:'current',screen:activeScreen,mode,unitId:selected,plan}];}catch(err){return tell(err.message);}if(!jobs.length)return tell('先に制作設定でカットを保存してください。');if(jobs.reduce((n,j)=>n+j.plan.count,0)>1441)return tell('一括出力は合計1441枚以内にしてください。');const controller=new AbortController();videoJob=controller;exportBusy=true;playing=false;const view={...captureView(),aspect:plan.aspect},stamp=$('export-stamp').checked,chosen=selected;
  const controls=[...document.querySelectorAll('.export-grid input,.export-grid select,#export-stamp,#export-transparent,#video-start')];controls.forEach(el=>el.disabled=true);$('video-cancel').textContent='中止';$('video-progress').hidden=false;$('video-progress').value=0;$('video-message').textContent='出力形式を確認しています…';
  const canvas=$('export-canvas');canvas.width=plan.width;canvas.height=plan.height;canvas.hidden=true;
  try{
   if(plan.format==='webm')await vp8Config(plan);abortIfNeeded(controller.signal);
   const replay=await replayForVideo(Math.max(...jobs.map(j=>j.plan.end)),view,controller.signal,(f,max)=>{if($('video-message')){$('video-message').textContent=`動きを計算中 ${f} / ${max} frame`;$('video-progress').value=max?f/max*25:25;}});
   abortIfNeeded(controller.signal);const bg=await exportBackground(view,controller.signal);canvas.hidden=false;
   const files=[];let bytes=0;
   for(const [jobIndex,job] of jobs.entries()){
    const result=await exportFrames({plan:job.plan,canvas,signal:controller.signal,metadata:{project:project.title,engineVersion:project.engineVersion,simulationSecondsPerFrame:project.secondsPerFrame,view:{...view,screen:job.screen,mode:job.mode},stamp,transparent},render:async(f,c,signal)=>{const alpha=transparent&&job.screen==='tactical',context={project,states:replayFrame(replay,f),frame:f,mode:job.mode,layers:alpha?{...view.layers,terrain:false}:view.layers,selected:job.unitId,backgroundView:alpha?null:bg,pixel:view.pixel,radarHide:view.radarHide,radarTrail:view.radarTrail};await paintSvg(c,job.screen==='tactical'?renderDocument(context,{...job.plan,...cameraAt(project,f,context.states,{zoom:view.zoom,center:view.center}),stamp,transparent:alpha}):renderOperationsDocument({...context,events:replay.events},{...job.plan,screen:job.screen,radarId:view.consoleRadarId,unitId:job.unitId,filter:view.consoleFilter,page:view.consolePage,facilityFilter:view.facilityFilter}),signal,{transparent:alpha});},onProgress:(n,total)=>{if($('video-message')){$('video-message').textContent=`出力 ${jobIndex+1}/${jobs.length} : ${n}/${total}枚`;$('video-progress').value=25+(jobIndex+n/total)/jobs.length*75;}}});
    abortIfNeeded(controller.signal);bytes+=result.size;if(bytes>MAX_EXPORT_BYTES)throw Error('一括出力が128MBを超えました。区間か解像度を下げてください。');files.push({name:job.name.replace(/[\\/:*?"<>|]/g,'_')+(plan.format==='webm'?'.webm':'-frames.zip'),data:new Uint8Array(await result.arrayBuffer())});
   }
   const output=jobs.length===1?new Blob([files[0].data]):new Blob([zipStored(files)]);download(basename()+(jobs.length===1?'-'+files[0].name:'-batch.zip'),output);$('video-progress').value=100;$('video-message').textContent=`保存しました：${jobs.length}出力 / ${(output.size/1024/1024).toFixed(1)}MB`;tell('映像・連番を書き出しました。');
  }catch(err){if($('video-message'))$('video-message').textContent=controller.signal.aborted?'書き出しを中止しました。途中のファイルは保存していません。':err.message;if(!controller.signal.aborted)tell(err.message);}
  finally{exportBusy=false;videoJob=null;controls.forEach(el=>el.disabled=false);if($('video-cancel'))$('video-cancel').textContent='閉じる';if($('video-start'))summarize();}
 };
};

