function renderOperations(){if(activeScreen==='tactical')return;if(activeScreen==='mapedit'){if(!$('beta-panel').querySelector('.map-editor'))mapEditor=mountMapEditor($('beta-panel'),{getProject:()=>project,change:fn=>{const ok=edit(()=>fn(project));backgroundView=project.background;return ok;},download,tell,editFacility,readonly:!!readonlyReplay});else mapEditor?.sync();return;}if(activeScreen==='settings'){if(!$('beta-panel').querySelector('.settings-page'))renderSettings();return;}if(activeScreen==='help'){$('beta-panel').innerHTML=guideHTML();return;}const radars=resolveRadars(project,sceneContext().states,frame);if(!radars.some(r=>r.id===consoleRadarId))consoleRadarId=radars[0]?.id||'';consolePage=Math.min(consolePage,Math.max(0,Math.ceil((activeScreen==='weapons'?weaponMounts(project,selected||project.units[0]?.id).length:activeScreen==='facilities'?filterFacilities(project,facilityFilter).length:project.units.length)/(activeScreen==='weapons'?weaponPageSize(project):20))-1));syncOptions('operations-unit',project.units.map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join(''),selected||'');syncOptions('operations-radar',radars.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join(''),consoleRadarId);syncOptions('operations-page',Array.from({length:Math.max(1,Math.ceil((activeScreen==='weapons'?weaponMounts(project,selected||project.units[0]?.id).length:activeScreen==='facilities'?filterFacilities(project,facilityFilter).length:project.units.length)/(activeScreen==='weapons'?weaponPageSize(project):20)))},(_,i)=>`<option value="${i}">${i+1}</option>`).join(''),consolePage);$('facility-filters').hidden=activeScreen!=='facilities';$('facility-search').value=facilityFilter.search;$('facility-filter-type').value=facilityFilter.type;$('facility-filter-team').value=facilityFilter.team;$('facility-ops').hidden=!['damage','facilities'].includes(activeScreen);$('delivery-ops').hidden=activeScreen!=='logistics';$('support-action').hidden=activeScreen!=='support';$('briefing-edit').hidden=activeScreen!=='briefing';$('weapons-edit').hidden=activeScreen!=='weapons';$('weapons-edit').textContent=weaponsEditing?'表示に戻る':'武装を編集';$('weapons-edit').setAttribute('aria-pressed',String(weaponsEditing));$('vls-action').hidden=activeScreen!=='weapons'||!weaponsEditing;$('aviation-action').hidden=activeScreen!=='aviation';$('operations-filter').value=consoleFilter;$('operations-radar-label').hidden=activeScreen!=='waveform';$('operations-filter-label').hidden=!['comms','cic'].includes(activeScreen);$('operations-page-label').hidden=!['status','damage','aviation','facilities','logistics','weapons'].includes(activeScreen);$('operations-title').textContent=SCREENS[activeScreen]+(pendingBattle?' / 計算中':'');if(activeScreen==='weapons'&&weaponsEditing&&!recording){mountWeapons($('operations-surface'),{project,states:sceneContext().states,hostId:selected,frame,change:fn=>edit(()=>fn(project)),tell,readonly:!!readonlyReplay});return;}$('operations-surface').innerHTML=renderOperationsDocument({...sceneContext(),events:displayedEvents()},{screen:activeScreen,radarId:consoleRadarId,unitId:selected,filter:consoleFilter,page:consolePage,facilityFilter});}
function switchScreen(screen){if(exportBusy||!Object.hasOwn(SCREENS,screen))return;activeScreen=screen;document.body.classList.toggle('map-editing',screen==='mapedit');$('beta-panel').innerHTML='';document.querySelector('.workspace').hidden=screen!=='tactical';document.querySelector('.palette').hidden=screen!=='tactical';$('operations').hidden=['tactical','settings','help','mapedit'].includes(screen);$('beta-panel').hidden=!['settings','help','mapedit'].includes(screen);if(['settings','help','mapedit'].includes(screen))playing=false;document.querySelectorAll('[data-screen]').forEach(b=>{b.classList.toggle('active',b.dataset.screen===screen);if(b.dataset.screen===screen)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(screen==='tactical'){fitMap();draw();}updateClock();}
