async function exportOperationsImage(){if(pendingBattle||exportBusy)return tell('計算・出力の完了をお待ちください。');playing=false;updateClock();try{const canvas=document.createElement('canvas');canvas.width=1920;canvas.height=1080;await paintSvg(canvas,renderOperationsDocument({...sceneContext(),events:displayedEvents()},{width:1920,height:1080,screen:activeScreen,radarId:consoleRadarId,unitId:selected,filter:consoleFilter,page:consolePage,facilityFilter}));const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw new Error('PNGを作成できませんでした。');download(basename()+'-'+activeScreen+'-F'+frame+'.png',blob);}catch(e){tell(e.message);}}
function communicationsEditor(id=''){const existing=project.communications.find(m=>m.id===id),m=existing||{at:frame,unitId:selected||'',channel:'command',text:''};modal('演出用の通信を編集',`<p class="hint">同じframeで同じ通信を表示します。戦闘命令は変更しません。最大2000件・本文240文字。</p><label class="field">通信<select id="comm-entry"><option value="">新しい通信</option>${project.communications.map(v=>`<option value="${esc(v.id)}" ${v.id===id?'selected':''}>F${v.at} / ${esc(v.text.slice(0,45))}</option>`).join('')}</select></label><div class="field-row"><label class="field">frame<input id="comm-at" type="number" min="0" max="10000" value="${m.at}"></label><label class="field">種別<select id="comm-channel">${Object.entries(CHANNELS).map(([k,v])=>`<option value="${k}" ${m.channel===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">部隊<select id="comm-unit"><option value="">司令部 / 全体</option>${project.units.map(u=>`<option value="${esc(u.id)}" ${u.id===m.unitId?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label></div><label class="field">定型文<select id="comm-template"><option value="">選択して本文に挿入</option>${['各部隊、状況を報告せよ。','配置完了。次の指示を待つ。','レーダーに反応。識別を継続。','損傷を確認。復旧作業を開始。','予定の行動を完了。'].map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">本文<textarea id="comm-text" maxlength="240" rows="4">${esc(m.text)}</textarea></label><div class="command-tools"><button id="comm-save">${existing?'更新':'追加'}</button><button id="comm-delete" ${existing?'':'disabled'}>削除</button></div>`);$('comm-entry').onchange=e=>communicationsEditor(e.target.value);$('comm-template').onchange=e=>{if(e.target.value)$('comm-text').value=e.target.value;};$('comm-save').onclick=()=>{const value={id:existing?.id||'',at:Number($('comm-at').value),unitId:$('comm-unit').value,channel:$('comm-channel').value,text:$('comm-text').value};if(edit(()=>{if(existing)Object.assign(project.communications.find(v=>v.id===id),value);else{let n=1;while(project.communications.some(v=>v.id==='comm-'+n))n++;value.id='comm-'+n;project.communications.push(value);}}))communicationsEditor(value.id);};$('comm-delete').onclick=()=>{if(edit(()=>{project.communications=project.communications.filter(v=>v.id!==id);}))communicationsEditor();};}
