function scheduledEditor(u){
 $('timeline').insertAdjacentHTML('beforeend',`<div class="command-box"><b>初期経路の完了後</b>${completionFields(u,'base')}<p class="hint">「移動」で最後の経由地の待機を終えた後に適用。戦闘ON時に有効です。</p></div>`);$('timeline').querySelectorAll('[data-after-base]').forEach(el=>el.onchange=()=>{if(el.value===''||!el.checkValidity())return tell('入力値を確認してください。');edit(()=>u[el.dataset.afterBase]=el.type==='number'?Number(el.value):el.value,{quiet:true});});
 const rows=u.orders||[];
 $('timeline').insertAdjacentHTML('beforeend',`<h3>予定命令 <small>${rows.length} / 50</small></h3><p class="hint">指定frameで命令を切り替えます。戦闘OFFでも予定移動を実行。移動は切り替え時の位置から指定座標へ向かいます。</p>`+rows.map((o,i)=>`<div class="command"><div class="command-head"><strong>${dateAt(project,o.at*(project.secondsPerFrame??60)).full}</strong><span>予定命令 ${i+1}${o.groupName?' / '+esc(o.groupName):''}</span></div><div class="command-box"><label class="field">開始frame<input data-order="${i}" data-key="at" type="number" min="${Math.ceil(u.start)}" max="${project.duration-1}" step="1" value="${o.at}"></label><label class="field">行動<select data-order="${i}" data-key="action">${actionOptions(u).map(([k,v])=>`<option value="${k}" ${o.action===k?'selected':''}>${v}</option>`).join('')}</select></label>${o.action==='move'?`<label class="field">この命令の速度 km/h（空欄＝部隊設定）<input data-order-speed="${i}" type="number" min="0.1" max="20000" step="any" value="${o.speed??''}"></label>${scheduledPointFields(o,i)}${completionFields(o,i)}`:''}${['fire','defend','assault','follow','merge'].includes(o.action)?`<label class="field">対象<select data-order="${i}" data-key="target"><option value="">${['follow','merge'].includes(o.action)?'対象を選択':'自動選択'}</option>${orderTargets(u,o.action).map(v=>`<option value="${esc(v.id)}" ${o.target===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label>`:''}<button class="danger" data-order-remove="${i}">命令を削除</button></div></div>`).join('')+'<button class="add-route" id="add-order">＋ 予定命令を追加</button><button class="add-route" id="order-template">待機 → 移動 → 防衛を追加</button>');
 $('timeline').querySelectorAll('[data-order]').forEach(el=>el.onchange=()=>{if(el.value===''||!el.checkValidity())return tell('範囲内の値を入力してください。');setTool('select');const i=Number(el.dataset.order),key=el.dataset.key;edit(()=>{const o=u.orders[i];o[key]=el.type==='number'?Number(el.value):el.value;if(['x','y'].includes(key))o[key]=Number(el.value)/(key==='x'?project.widthKm:project.heightKm)*1000;if(key==='action'){if(o.action==='move'&&!o.points.length)o.points=[{x:o.x,y:o.y,wait:0}];o.target=['follow','merge'].includes(o.action)?orderTargets(u,o.action)[0]?.id||'':'';}},{quiet:true});});
 $('timeline').querySelectorAll('[data-order-speed]').forEach(el=>el.onchange=()=>{if(!el.checkValidity())return tell('速度の入力範囲を確認してください。');edit(()=>{const o=u.orders[Number(el.dataset.orderSpeed)];if(el.value==='')delete o.speed;else o.speed=Number(el.value);},{quiet:true});});wireScheduledPoints(u);
 $('timeline').querySelectorAll('[data-order-remove]').forEach(el=>el.onclick=()=>edit(()=>u.orders.splice(Number(el.dataset.orderRemove),1)));
 const nextTime=()=>Math.max(Math.ceil(u.start),rows.length?Math.max(...rows.map(o=>o.at))+1:Math.ceil(u.start)+1);
 $('add-order').onclick=()=>edit(()=>u.orders.push({at:nextTime(),action:'wait',target:'',x:u.x,y:u.y}));
 $('order-template').onclick=()=>{if(u.type==='missile'&&u.missileFlight)return tell('専用ミサイルは攻撃・発射待機の予定命令を設定してください。');return edit(()=>{let at=nextTime();u.orders.push({at,action:'wait',target:'',x:u.x,y:u.y},{at:at+2,action:'move',target:'',x:clamp(u.x+100,0,1000),y:u.y},{at:at+7,action:'defend',target:'',x:u.x,y:u.y});});};
}
function orderTargets(u,action){return project.units.filter(v=>v.id!==u.id&&(['follow','merge'].includes(action)?v.team===u.team&&(action!=='merge'||v.type===u.type&&project.defaults.find(t=>t.id===u.type).domain==='land'):v.team!==u.team&&v.team!=='neutral'));}

$('radar-settings').onclick=()=>{
 if(readonlyReplay)return tell('固定リプレイのレーダーを変更するには「編集用に開く」を押してください。');
 let draft=copy(project.radars),active=draft[0]?.id;
 function read(){const r=draft.find(r=>r.id===active);if(!r)return true;const inputs=[...$('modal-body').querySelectorAll('[data-radar-field]')];if(inputs.some(el=>!el.checkValidity()||(el.type==='number'&&el.value===''))){tell('レーダー設定の入力範囲を確認してください。');return false;}for(const el of inputs){const k=el.dataset.radarField;r[k]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value.trim();if(k==='x'||k==='y')r[k]=r[k]/(k==='x'?project.widthKm:project.heightKm)*1000;}return true;}
 function save(){return read()&&edit(()=>project.radars=copy(draft),{quiet:true});}
 function show(){const r=draft.find(r=>r.id===active);modal('レーダー管理',`<p class="hint">設定はプロジェクト・固定リプレイ・動画に含まれます。探知は表示演出で、戦闘判断には影響しません。</p><div class="field-row"><label>レーダー ${draft.length} / 16<select id="radar-select">${draft.map(v=>`<option value="${esc(v.id)}" ${v.id===active?'selected':''}>${esc(v.name)}${v.enabled?'':'（無効）'}</option>`).join('')}</select></label><button id="radar-add" ${draft.length>=16?'disabled':''}>＋ レーダー追加</button></div>${r?`<label class="field">名前<input data-radar-field="name" value="${esc(r.name)}" maxlength="60" required></label><label class="field">固定局の所属（追従局は部隊の陣営を使用）<select data-radar-field="team">${[['blue','青'],['red','赤'],['neutral','中立']].map(([v,n])=>`<option value="${v}" ${(r.team||'blue')===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">探知する陣営<select data-radar-field="detectTarget">${[['enemy','敵陣営のみ（標準）'],['all','全陣営'],['blue','青のみ'],['red','赤のみ'],['neutral','中立のみ']].map(([v,n])=>`<option value="${v}" ${(r.detectTarget||'enemy')===v?'selected':''}>${n}</option>`).join('')}</select></label><p class="hint">敵陣営：青→赤、赤→青。中立局は標準では作動しません。有効化する場合は探知対象を明示し、有効にするをONにします。</p><label class="field">探知区分<select data-radar-field="detectMode">${[['all','対空・対地/対艦'],['air','対空'],['surface','対地/対艦']].map(([v,n])=>`<option value="${v}" ${(r.detectMode||'all')===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">中心の追従先<select data-radar-field="unitId"><option value="">固定地点</option>${project.units.map(u=>`<option value="${esc(u.id)}" ${r.unitId===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><p class="hint">追従中は部隊の位置を中心にします。開始前・壊滅・撃沈・合流済みでは停止します。下の中心座標は固定地点用です。</p><label class="check"><input data-radar-field="enabled" type="checkbox" ${r.enabled?'checked':''}> このレーダーを有効にする</label><div class="field-row">${['x','y'].map(k=>`<label>中心 ${k.toUpperCase()} km<input data-radar-field="${k}" type="number" step="any" min="0" max="${k==='x'?project.widthKm:project.heightKm}" value="${r[k]/1000*(k==='x'?project.widthKm:project.heightKm)}"></label>`).join('')}</div><div class="field-row"><label>探知半径 km<input data-radar-field="radiusKm" type="number" min="0.01" max="2000" step="any" value="${r.radiusKm}"></label><label>回転速度 度 / 作中1分<input data-radar-field="speed" type="number" min="-3600" max="3600" step="any" value="${r.speed}"></label></div><label class="field">初期方位 度（北0・東90）<input data-radar-field="phase" type="number" min="0" max="359.999999" step="any" value="${r.phase}"></label><p class="hint">標準30度＝作中12分で1周。負の速度で逆回転、0で停止。再生速度を変えても同じframeの方位は変わりません。</p><div class="field-row"><button id="radar-place">適用して中心を地図で指定</button><button id="radar-remove" class="danger">このレーダーを削除</button></div>`:'<p class="empty">レーダーがありません。追加すると探知範囲を設定できます。</p>'}<p class="hint">「走査による表示制限」は有効なレーダーの探知範囲を合成します。0基では探知時表示の部隊を隠します。常時表示は残ります。残光は現在位置に表示し、過去位置の航跡ではありません。</p><div class="dialog-actions"><button id="radar-cancel">キャンセル</button><button id="radar-save" class="primary">適用</button></div>`);
 $('radar-select').onchange=e=>{const id=e.target.value;if(read()){active=id;show();}else e.target.value=active;};
 $('radar-add').onclick=()=>{if(!read()||draft.length>=16)return;let n=1;while(draft.some(r=>r.id==='r'+n))n++;active='r'+n;draft.push({id:active,name:'レーダー '+n,x:500,y:500,radiusKm:Math.min(project.widthKm,project.heightKm)*.25,speed:30,phase:0,enabled:true});show();};
 if(r){$('radar-remove').onclick=()=>{draft=draft.filter(v=>v.id!==active);active=draft[0]?.id;show();};$('radar-place').onclick=()=>{const follow=$('modal-body').querySelector('[data-radar-field=unitId]');if(follow.value)return tell('固定地点に切り替えてから中心を配置してください。');if(save()){placingRadar=active;$('modal').close();setTool('radar');}};}
 $('radar-save').onclick=()=>{if(save()){$('modal').close();tell('レーダー設定を保存しました。');}};$('radar-cancel').onclick=()=>$('modal').close();
 }
 show();
};

function completionFields(o,index){const attr=k=>index==='base'?`data-after-base="${k}"`:`data-order="${index}" data-key="${k}"`;return `<label class="field">移動完了後<select ${attr('afterAction')}>${Object.entries({none:'変更しない',wait:'待機',defend:'防衛'}).map(([k,v])=>`<option value="${k}" ${(o.afterAction||'none')===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">切替前の待機 / 分<input ${attr('afterWait')} type="number" min="0" max="10000" step="1" value="${o.afterWait||0}"></label>`;}

function scheduledPointFields(o,i){const estimate=forecastOrders(project,current(),frame,viewState(current())).get(o.at);return `<p class="hint">経由地 ${o.points.length} / 100 · 開始時の実位置から移動</p>`+o.points.map((p,j)=>`<fieldset class="planned-point"><legend>経由地 ${j+1}</legend><p class="hint">予想到着 ${estimate?.events.find(e=>e.kind==='到着'&&e.index===j)?dateAt(project,estimate.events.find(e=>e.kind==='到着'&&e.index===j).time).full:'通行不可'}（交戦除外）</p><div class="field-row">${['x','y'].map(k=>`<label>${k.toUpperCase()} km<input data-op="${i}" data-pi="${j}" data-pk="${k}" type="number" min="0" max="${k==='x'?project.widthKm:project.heightKm}" step="any" value="${p[k]/1000*(k==='x'?project.widthKm:project.heightKm)}"></label>`).join('')}</div><label class="field">待機 / 分<input data-op="${i}" data-pi="${j}" data-pk="wait" type="number" min="0" max="10000" step="any" value="${p.wait}"></label><div class="command-tools"><button data-op-action="up" data-oi="${i}" data-pi="${j}" ${j===0?'disabled':''}>前へ</button><button data-op-action="down" data-oi="${i}" data-pi="${j}" ${j===o.points.length-1?'disabled':''}>後へ</button><button data-op-action="remove" data-oi="${i}" data-pi="${j}" ${o.points.length===1?'disabled':''}>削除</button></div></fieldset>`).join('')+`<div class="field-row"><button data-op-action="add" data-oi="${i}" ${o.points.length>=100?'disabled':''}>＋ 地点</button><button data-op-action="map" data-oi="${i}" ${o.points.length>=100?'disabled':''}>地図で追加</button></div>`;}
function wireScheduledPoints(u){
 $('timeline').querySelectorAll('[data-op]').forEach(el=>el.onchange=()=>{if(el.value===''||!el.checkValidity())return tell('経由地の入力範囲を確認してください。');const k=el.dataset.pk;edit(()=>u.orders[Number(el.dataset.op)].points[Number(el.dataset.pi)][k]=Number(el.value)/(k==='wait'?1:k==='x'?project.widthKm/1000:project.heightKm/1000),{quiet:true});});
 $('timeline').querySelectorAll('[data-op-action]').forEach(el=>el.onclick=()=>{const o=u.orders[Number(el.dataset.oi)],j=Number(el.dataset.pi),action=el.dataset.opAction;if(action==='map'){if(readonlyReplay)return;placingOrder={unit:u.id,at:o.at};setTool('order-route');return;}edit(()=>{if(action==='add'){if(o.points.length>=100)return;o.points.push({...o.points.at(-1),wait:0});}else if(action==='remove'){if(o.points.length>1)o.points.splice(j,1);}else{const k=j+(action==='up'?-1:1);if(k>=0&&k<o.points.length)[o.points[j],o.points[k]]=[o.points[k],o.points[j]];}},{quiet:true});});
}

const openSamples=$('sample').onclick;
$('sample').textContent='サンプル・テンプレート';
$('sample').onclick=()=>{if(exportBusy)return;openSamples();$('modal-body').insertAdjacentHTML('afterbegin','<button id="custom-templates" class="primary add-route">自作テンプレートを保存・開く</button>');$('custom-templates').onclick=()=>openTemplateLibrary();};
function openTemplateLibrary(selectedId){
 let entries;try{entries=readTemplates(localStorage);}catch(err){tell('自作テンプレートを読み込めません：'+err.message);return;}
 const chosen=entries.find(t=>t.id===selectedId)||entries[0];
 modal('自作テンプレート',`<p class="hint">このブラウザーに最大12件保存。部隊・命令・地形・背景・レーダー・兵科既定値を含みます。別端末への移動には書き出しを使ってください。</p><div class="field-row"><button id="template-new" class="primary" ${entries.length>=12?'disabled':''}>現在の設定を保存</button><button id="template-import">ファイルから追加</button></div><input id="template-file" type="file" accept=".mfdcotemplate,.mfdcosim,application/json" hidden>${chosen?`<label class="field">保存済み ${entries.length} / 12<select id="template-select">${entries.map(t=>`<option value="${t.id}" ${t.id===chosen.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><img id="template-preview" class="template-preview" alt="0frameのテンプレートプレビュー"><p class="hint">0frame · ${chosen.project.units.length}部隊 · ${chosen.project.duration}frame · ${chosen.project.radars.length}レーダー</p><p class="template-note">${esc(chosen.note||'メモなし')}</p><div class="template-actions"><button id="template-use" class="primary">この設定で作成</button><button id="template-export">書き出す</button><button id="template-rename">名前・メモ</button><button id="template-delete" class="danger">削除</button></div>`:'<p class="empty">自作テンプレートはまだありません。現在の設定を保存して、次の映像制作で再利用できます。</p>'}`);
 $('template-new').onclick=()=>editTemplateMetadata();$('template-import').onclick=()=>$('template-file').click();
 $('template-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>32*1024*1024)return tell('32MB以下のファイルを選択してください。');try{const record=readTemplate(JSON.parse(await file.text())),next=appendTemplate(readTemplates(localStorage),record);writeTemplates(localStorage,next);openTemplateLibrary(next.at(-1).id);tell('テンプレートを追加しました。');}catch(err){tell('追加できません：'+err.message);}};
 if(!chosen)return;
 const p=chosen.project,states=p.units.map(u=>({id:u.id,x:u.x,y:u.y,hp:u.hp,maxHp:u.hp,personnel:u.personnel,status:u.start?'開始待ち':'待機'})),layers={units:true,hp:true,quantity:true,echelon:true,names:true,labels:true,terrain:true,facilities:true,grid:true,routes:false,ranges:false};
 const svg=renderDocument({project:p,states,frame:0,mode:chosen.mode,layers,selected:null,backgroundView:p.background,radarHide:false},{width:640,height:400});$('template-preview').src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
 $('template-select').onchange=e=>openTemplateLibrary(e.target.value);
 $('template-use').onclick=()=>confirmReplace('テンプレートから作成',()=>{checkpoint();project=validate(chosen.project);restoreChanged();$('mode-'+chosen.mode).click();$('radar-hide').checked=false;draw();tell('テンプレートのコピーを開きました。元の設定は保持されています。');});
 $('template-export').onclick=()=>{const record=readTemplate(chosen);download(chosen.name.replace(/[\\/:*?"<>|]/g,'_')+'.mfdcotemplate',JSON.stringify(record),'application/json');};
 $('template-rename').onclick=()=>editTemplateMetadata(chosen);
 $('template-delete').onclick=()=>{modal('テンプレートを削除',`<p>「${esc(chosen.name)}」をこの端末から削除します。現在編集中のシナリオは残ります。</p><div class="dialog-actions"><button id="template-keep">戻る</button><button id="template-remove" class="danger">削除する</button></div>`);$('template-keep').onclick=()=>openTemplateLibrary(chosen.id);$('template-remove').onclick=()=>{try{writeTemplates(localStorage,readTemplates(localStorage).filter(t=>t.id!==chosen.id));openTemplateLibrary();}catch(err){tell(err.message);}};};
}
function editTemplateMetadata(existing){
 modal(existing?'テンプレートの名前・メモ':'現在の設定をテンプレート保存',`<label class="field">名前<input id="template-name" maxlength="80" required value="${esc(existing?.name||project.title.slice(0,80))}"></label><label class="field">メモ<textarea id="template-note" rows="4" maxlength="300">${esc(existing?.note||'')}</textarea></label><p class="hint">${existing?'部隊や命令の設定は変更しません。':'再生中の位置ではなく、0frameの初期配置と全命令を保存します。背景画像も含まれます。'}</p><div class="dialog-actions"><button id="template-back">戻る</button><button id="template-store" class="primary">保存</button></div>`);
 $('template-back').onclick=()=>openTemplateLibrary(existing?.id);$('template-store').onclick=()=>{try{const record=templateRecord(existing?.project||project,$('template-name').value,$('template-note').value,existing?.mode||mode),list=readTemplates(localStorage);let next;if(existing){if(!list.some(t=>t.id===existing.id))throw new Error('このテンプレートは別の操作で削除されています。');next=list.map(t=>t.id===existing.id?{id:t.id,...record}:t);}else next=appendTemplate(list,record);writeTemplates(localStorage,next);openTemplateLibrary(existing?.id||next.at(-1).id);tell('テンプレートを保存しました。');}catch(err){tell(err.message);}};
}

function actionOptions(u){return u.type==='missile'&&u.missileFlight?[['assault','攻撃'],['wait','発射待機']]:Object.entries(ACTIONS);}
function missileInspector(u){if(u.type!=='missile')return;
 $('inspector').insertAdjacentHTML('afterbegin',`<div class="command-box"><label class="check"><input id="missile-flight" type="checkbox" ${u.missileFlight?'checked':''}>専用飛翔・着弾を使う</label><label class="field">発射方位 °（北0・東90）<input data-field="heading" type="number" min="0" max="359.999" step="any" value="${u.heading??90}"></label><label class="field">同時発射数<input data-field="salvo" type="number" min="1" max="1000" step="1" value="${u.salvo||1}"></label><div class="field-row"><label>速度<input id="missile-speed-value" type="number" min="0" step="any" value="${u.speed/3600}"></label><label>単位<select id="missile-speed-unit">${Object.keys(SPEED_FACTORS).map(k=>`<option ${k==='km/s'?'selected':''}>${k}</option>`).join('')}</select></label></div><button id="missile-speed-apply">速度を適用</button><p class="hint">戦闘ON＋攻撃で発射。目標未指定は前方180°の最寄りをロック。発射数は同時着弾する一群です。Mach基準は343m/s固定。</p></div>`);
 $('missile-flight').onchange=e=>edit(()=>{u.missileFlight=e.target.checked;if(u.missileFlight&&!['assault','wait'].includes(u.action))u.action='assault';});
 $('missile-speed-unit').onchange=e=>$('missile-speed-value').value=speedFromKmh(u.speed,e.target.value);
 $('missile-speed-apply').onclick=()=>{try{if(!$('missile-speed-value').value)throw new Error('速度を入力してください。');const speed=speedToKmh(Number($('missile-speed-value').value),$('missile-speed-unit').value);edit(()=>u.speed=speed);}catch(err){tell(err.message);}};
}

function targetDomainInspector(u){$('inspector').querySelector('[data-field=action]').closest('label').insertAdjacentHTML('beforebegin',`<fieldset class="planned-point"><legend>攻撃対象</legend>${Object.entries({land:'陸上',sea:'海上',air:'空・ミサイル'}).map(([key,label])=>`<label class="check"><input data-target-domain="${key}" type="checkbox" ${(u.targetDomains||['land','sea','air']).includes(key)?'checked':''}>${label}</label>`).join('')}<p class="hint">指定目標・自動選択に適用。全てOFFで攻撃禁止。戦闘ON時に有効。</p></fieldset>`);$('inspector').querySelectorAll('[data-target-domain]').forEach(el=>el.onchange=()=>{const domains=[...$('inspector').querySelectorAll('[data-target-domain]:checked')].map(el=>el.dataset.targetDomain);edit(()=>u.targetDomains=domains,{quiet:true});});}

$('damage-scale').onchange=e=>{if(e.target.value===''||!e.target.checkValidity())return tell('損害倍率は0.001〜10で入力してください。');edit(()=>project.damageScale=Number(e.target.value));};$('attrition-firepower').onchange=e=>edit(()=>project.attritionFirepower=e.target.checked);$('return-fire').onchange=e=>edit(()=>project.returnFire=e.target.checked);

function refreshExtensions(){refreshGroups();for(const [id,key]of [['unit-scale','unitScale'],['facility-scale','facilityScale'],['terrain-resolution','terrainCols']])$(id).value=project[key];$('facility-effects').checked=project.facilityEffects;$('radar-team').value=project.radarTeams.length===1?project.radarTeams[0]:'all';}
for(const [id,key]of [['unit-scale','unitScale'],['facility-scale','facilityScale']])$(id).onchange=e=>edit(()=>project[key]=Number(e.target.value));
$('facility-effects').onchange=e=>edit(()=>project.facilityEffects=e.target.checked);
$('terrain-resolution').onchange=e=>edit(()=>resizeTerrain(project,Number(e.target.value)));
$('radar-team').onchange=e=>edit(()=>project.radarTeams=e.target.value==='all'?['blue','red','neutral']:[e.target.value]);
document.querySelectorAll('[data-facility-tool]').forEach(el=>el.onclick=()=>setTool(el.dataset.facilityTool));
function placeFacility(p){if(readonlyReplay)return;const kind=tool;if(FACILITY_LINE_TYPES.includes(kind)&&!facilityAnchor){facilityAnchor=p;tell('線の終点をクリックしてください。');return;}const radius=Number($('facility-radius').value);if(!Number.isFinite(radius)||radius<.01||radius>20)return tell('設備半径は0.01〜20kmです。');const ok=edit(()=>{let id;do{id='f'+project.nextId++;}while(project.facilities.some(f=>f.id===id));project.facilities.push({id,type:kind,team:$('facility-team').value,radiusKm:radius,defense:kind==='trench'?100:kind==='bunker'?150:kind==='fort'?250:0,damage:kind==='minefield'?200:0,supportRate:['hospital','army_base','naval_base','airfield'].includes(kind)?1:0,points:FACILITY_LINE_TYPES.includes(kind)?[facilityAnchor,p]:[p]});},{quiet:true});if(ok&&FACILITY_LINE_TYPES.includes(kind))facilityAnchor=p;}


$('palette-team').onchange=()=>palette();
$('radar-policy').onclick=()=>{modal('レーダーの表示条件',`<p class="hint">走査による表示制限がONのときに適用します。標準は青・中立を常時表示、赤を探知時に表示します。</p>${[['blue','青陣営'],['red','赤陣営'],['neutral','中立']].map(([t,n])=>`<label class="field">${n}<select data-radar-policy="${t}">${[['always','常時表示'],['scan','探知したとき表示'],['hidden','非表示']].map(([v,label])=>`<option value="${v}" ${project.radarPolicy[t]===v?'selected':''}>${label}</option>`).join('')}</select></label>`).join('')}<label class="field">自軍として探知距離を使う陣営<select id="observer-team"><option value="blue" ${project.observerTeam==='blue'?'selected':''}>青</option><option value="red" ${project.observerTeam==='red'?'selected':''}>赤</option></select></label><p class="hint">交戦中の双方と、自軍部隊の探知距離に入った敵も表示します。判定順：画面の陣営絞込 → 部隊ごとの常時表示 → 上の陣営設定 → 稼働局の探知対象・対空/対地・半径・走査角。探知の有無は戦闘計算には影響しません。</p><div class="dialog-actions"><button id="radar-policy-default">標準に戻す</button><button id="radar-policy-save" class="primary">適用</button></div>`);$('radar-policy-default').onclick=()=>document.querySelectorAll('[data-radar-policy]').forEach(el=>el.value=el.dataset.radarPolicy==='red'?'scan':'always');$('radar-policy-save').onclick=()=>{const policy=Object.fromEntries([...document.querySelectorAll('[data-radar-policy]')].map(el=>[el.dataset.radarPolicy,el.value]));const observer=$('observer-team').value;if(edit(()=>{project.radarPolicy=policy;project.observerTeam=observer;},{quiet:true}))$('modal').close();};};

$('palette-category').onchange=e=>{subfilter=e.target.value;palette();};
function refreshGroups(){if(!project.groups.some(g=>g.id===activeGroup))activeGroup='';$('group-select').innerHTML='<option value="">個別の部隊を編集</option>'+project.groups.map(g=>`<option value="${esc(g.id)}" ${g.id===activeGroup?'selected':''}>${esc(g.name)} (${g.members.length})</option>`).join('');$('group-status').textContent=activeGroup?'地図の点線枠が選択グループ':'最大50グループ / 部隊の重複登録可';}
$('group-select').onchange=e=>{activeGroup=e.target.value;setTool('select');refreshGroups();draw();};
$('groups-manage').onclick=()=>openGroups(activeGroup);
$('group-command-move').onclick=()=>{if(!activeGroup)return tell('グループを選択してください。');if(pendingBattle)return tell('現在frameの計算完了をお待ちください。');playing=false;updateClock();setTool('group-move');};
$('group-command-wait').onclick=()=>previewGroupCommand('wait');$('group-command-defend').onclick=()=>previewGroupCommand('defend');
function openGroups(id){if(readonlyReplay||exportBusy)return;const g=project.groups.find(g=>g.id===id);modal('グループの登録・編集',`<div class="field-row"><label>登録済み<select id="group-library"><option value="">新規グループ</option>${project.groups.map(v=>`<option value="${esc(v.id)}" ${v.id===id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><label>名前<input id="group-name" maxlength="60" required value="${esc(g?.name||'新規グループ')}"></label></div><label class="field">部隊を検索<input id="group-search" placeholder="部隊名・兵科"></label><div class="group-members">${project.units.map(u=>`<label data-member-name="${esc((u.name+' '+project.defaults.find(t=>t.id===u.type).name).toLowerCase())}" class="check"><input data-group-member="${esc(u.id)}" type="checkbox" ${(g?g.members.includes(u.id):u.id===selected)?'checked':''}><span style="color:${colors[u.team]}">${esc(u.name)}</span><small>${esc(project.defaults.find(t=>t.id===u.type).name)}</small></label>`).join('')}</div><p class="hint">登録後、左のグループ欄から一括移動・待機・防衛を設定します。一括命令は同じ陣営で使用します。グループを解散しても既に作成した命令は残ります。</p><div class="dialog-actions">${g?'<button id="group-delete" class="danger">解散</button>':''}<button id="group-save" class="primary">保存</button></div>`);$('group-library').onchange=e=>openGroups(e.target.value);$('group-search').oninput=e=>document.querySelectorAll('[data-member-name]').forEach(el=>el.hidden=!el.dataset.memberName.includes(e.target.value.toLowerCase()));$('group-save').onclick=()=>{const name=$('group-name').value.trim(),members=[...document.querySelectorAll('[data-group-member]:checked')].map(el=>el.dataset.groupMember);if(!name)return tell('グループ名を入力してください。');if(edit(()=>{if(g){g.name=name;g.members=members;activeGroup=g.id;}else{let next;do{next='g'+project.nextId++;}while(project.groups.some(v=>v.id===next));project.groups.push({id:next,name,members});activeGroup=next;}},{quiet:true}))$('modal').close();};if(g)$('group-delete').onclick=()=>{if(edit(()=>project.groups=project.groups.filter(v=>v.id!==g.id),{quiet:true}))$('modal').close();};}
function previewGroupCommand(action,dest){if(readonlyReplay||exportBusy)return;if(pendingBattle)return tell('現在frameの計算完了をお待ちください。');const g=project.groups.find(g=>g.id===activeGroup);if(!g)return tell('グループを選択してください。');const at=frame,states=project.units.map(u=>({id:u.id,...viewState(u)}));modal('グループ命令 / '+ACTIONS[action],`<p><b>${esc(g.name)}</b> · ${at}frameから実行</p>${action==='move'?'<label class="check"><input id="group-common-speed" type="checkbox" checked>最も遅い部隊の速度に合わせる（この命令のみ）</label>':''}<label class="check"><input id="group-replace" type="checkbox">同時刻の命令を置換</label><div id="group-plan-result"></div><p class="hint">現在の各部隊の配置間隔を目的地に反映します。地形・交戦・撤退により移動中の隊形は変わります。開始前・壊滅・合流済み・撤退中・修理中・専用ミサイルは対象外。</p><div class="dialog-actions"><button id="group-cancel">戻る</button><button id="group-apply" class="primary">命令を設定</button></div>`);let plan;const update=()=>{try{plan=groupPlan(project,g,states,at,dest,{action,commonSpeed:$('group-common-speed')?.checked??false,replace:$('group-replace').checked});$('group-plan-result').innerHTML=`<div class="group-plan"><table class="settings-table"><thead><tr><th>対象</th><th>予想到着</th></tr></thead><tbody>${plan.orders.map(v=>`<tr><td>${esc(v.name)}</td><td>${action==='move'?dateAt(project,v.arrival).full:'現在位置を維持'}</td></tr>`).join('')}</tbody></table></div>${plan.skipped.length?'<p class="hint">対象外：'+plan.skipped.map(esc).join('、')+'</p>':''}`;$('group-apply').disabled=false;}catch(err){plan=null;$('group-plan-result').innerHTML='<p class="warn">'+esc(err.message)+'</p>';$('group-apply').disabled=true;}};$('group-replace').onchange=update;if($('group-common-speed'))$('group-common-speed').onchange=update;$('group-cancel').onclick=()=>$('modal').close();$('group-apply').onclick=()=>{if(plan&&edit(()=>applyGroupPlan(project,plan),{quiet:true})){$('modal').close();tell(plan.orders.length+'部隊へ'+at+'frameの命令を設定しました。');}};update();}

function newProjectWithDefaults(){let p=fresh(true);p.manualHeight=false;p.mapAspect=16/9;p.heightKm=p.widthKm/p.mapAspect;try{const preset=JSON.parse(localStorage.getItem('mfdco-beta-defaults'));if(preset){for(const key of ['defaults','symbolOverrides','symbolMode','secondsPerFrame','damageScale','unitScale','missileDisplayMode','gridKm','mapAspect','manualHeight','logisticsEnabled','powerEnabled'])if(preset[key]!==undefined)p[key]=key==='defaults'?TYPES.map(t=>({...t,...(Array.isArray(preset.defaults)?preset.defaults.find(v=>v.id===t.id):{})})):preset[key];if(!p.manualHeight)p.heightKm=p.widthKm/p.mapAspect;p=validate(p);}}catch{}return p;}
function syncBetaControls(){if($('map-ratio')){$('map-ratio').value=String(project.mapAspect);$('map-manual-height').checked=project.manualHeight;$('map-height').disabled=!project.manualHeight||!!readonlyReplay;$('frame-seconds').value=project.secondsPerFrame;}}
function applyMapWidth(width){edit(()=>{project.widthKm=width;if(!project.manualHeight)project.heightKm=width/project.mapAspect;project.gridKm=niceGrid(width);});}
$('map-width').onchange=e=>applyMapWidth(Number(e.target.value));
$('map-height').onchange=e=>edit(()=>{project.heightKm=Number(e.target.value);project.mapAspect=project.widthKm/project.heightKm;});
$('map-height').parentElement.insertAdjacentHTML('afterend','<label>地図の比率<select id="map-ratio"><option value="1.7777777777777777">16:9</option><option value="1.6">16:10</option><option value="1.3333333333333333">4:3</option><option value="1">1:1</option></select></label><label class="check"><input id="map-manual-height" type="checkbox">縦幅を直接指定</label>');
$('map-ratio').onchange=e=>edit(()=>{project.mapAspect=Number(e.target.value);project.manualHeight=false;project.heightKm=project.widthKm/project.mapAspect;});
$('map-manual-height').onchange=e=>edit(()=>{project.manualHeight=e.target.checked;if(!project.manualHeight)project.heightKm=project.widthKm/project.mapAspect;});
$('play-rate').parentElement.insertAdjacentHTML('afterend','<label>作中 秒/frame<input id="frame-seconds" type="number" min="1" max="600" step="1" style="width:65px"></label>');
$('frame-seconds').onchange=e=>changeFrameRatio(Number(e.target.value));
function changeFrameRatio(value){edit(()=>{project.secondsPerFrame=value;});}
syncBetaControls();
function renderSettings(){const panel=$('beta-panel');panel.innerHTML=`<article class="guide settings-page"><h1>設定 <small>v${APP_VERSION}</small></h1><p>現在のプロジェクトに保存します。既定値を端末に保存すると、次の新規作品にも引き継ぎます。</p><section><h2>兵站・電力</h2><label><input id="setting-logistics" type="checkbox" ${project.logisticsEnabled?'checked':''}>兵站を有効化</label><label><input id="setting-power" type="checkbox" ${project.powerEnabled?'checked':''}>電力を有効化</label><button id="setting-infrastructure">兵站・電力を適用</button><p>燃料切れで車両等の移動停止、弾薬切れで射撃停止、食料切れで移動速度半減。補給施設の有限在庫を範囲内に配分します。電力は同陣営・同系統で共有し、不足率を施設の補給・回復に反映。送電線や実物の物理単位は扱いません。</p></section><section><h2>時間・表示</h2><div class="settings-fields"><label>時間比率<select id="setting-ratio">${[[600,'1frame＝10分'],[60,'1frame＝1分（標準）'],[6,'10frame＝1分'],[1,'60frame＝1分']].map(([v,n])=>`<option value="${v}" ${project.secondsPerFrame===v?'selected':''}>${n}</option>`).join('')}<option value="custom" ${![600,60,6,1].includes(project.secondsPerFrame)?'selected':''}>カスタム</option></select></label><label>作中 秒/frame<input id="setting-seconds" type="number" min="1" max="600" value="${project.secondsPerFrame}"></label><label>グリッド間隔 km<input id="setting-grid" type="number" min="0.01" max="1000" step="any" value="${project.gridKm}"></label><label>ミサイル表示<select id="setting-missiles"><option value="group" ${project.missileDisplayMode==='group'?'selected':''}>近接する発射群を集約</option><option value="individual" ${project.missileDisplayMode==='individual'?'selected':''}>発射群ごとに表示</option></select></label><label>記号表示<select id="setting-symbol"><option value="nato" ${project.symbolMode==='nato'?'selected':''}>NATO風の標準記号</option><option value="custom" ${project.symbolMode==='custom'?'selected':''}>ユーザー画像優先</option></select></label></div><p class="hint">比率変更では命令のframe番号を維持します。作中の命令時刻は変わります。戦闘・予定命令は総時間24時間以内です。</p><button id="setting-apply" class="primary">表示・時間設定を適用</button></section><section><h2>新規部隊・新規作品の既定値</h2><div class="command-tools"><button id="settings-units">兵科ごとの速度・HP・攻撃対象</button><button id="settings-store">端末の既定に保存</button><button id="settings-clear">端末の既定を解除</button></div><p id="settings-result" role="status"></p></section><section><h2>兵科記号の一覧と置換</h2><p>PNG・JPEG・WebP、1枚750KB以下。設定を「ユーザー画像優先」にすると反映します。未登録の兵科は標準記号を使います。</p><div class="symbol-catalog">${project.defaults.map(t=>`<div class="symbol-item">${icon(t.id)}<span>${esc(t.name)}</span><label class="file-button">画像を選択<input type="file" data-symbol-file="${t.id}" accept="image/png,image/jpeg,image/webp"></label><button data-symbol-reset="${t.id}" ${project.symbolOverrides[t.id]?'':'disabled'}>解除</button></div>`).join('')}</div></section><section><h2>フィードバック</h2><p>問題が起きた画面・操作・時間比率と、可能なら再現用プロジェクトを添えてください。</p><a class="primary" href="${FEEDBACK}" target="_blank" rel="noopener">フィードバックフォームを開く</a></section></article>`;
$('setting-infrastructure').onclick=()=>{const logistics=$('setting-logistics').checked,power=$('setting-power').checked;edit(()=>{project.logisticsEnabled=logistics;project.powerEnabled=power;});tell('兵站・電力設定を適用しました。');};$('setting-ratio').onchange=e=>{if(e.target.value!=='custom')$('setting-seconds').value=e.target.value;};$('setting-apply').onclick=()=>{const seconds=Number($('setting-seconds').value),grid=Number($('setting-grid').value),missiles=$('setting-missiles').value,symbolMode=$('setting-symbol').value;edit(()=>{project.secondsPerFrame=seconds;project.gridKm=grid;project.missileDisplayMode=missiles;project.symbolMode=symbolMode;});};$('settings-units').onclick=defaultsEditor;$('settings-store').onclick=()=>{try{const data={};for(const k of ['defaults','symbolOverrides','symbolMode','secondsPerFrame','damageScale','unitScale','missileDisplayMode','gridKm','mapAspect','manualHeight','logisticsEnabled','powerEnabled'])data[k]=project[k];localStorage.setItem('mfdco-beta-defaults',JSON.stringify(data));$('settings-result').textContent='次の新規作品から適用します。';}catch{tell('端末の保存容量を超えました。プロジェクトファイルを保存してください。');}};$('settings-clear').onclick=()=>{localStorage.removeItem('mfdco-beta-defaults');$('settings-result').textContent='新規作品は標準設定を使用します。';};panel.querySelectorAll('[data-symbol-reset]').forEach(b=>b.onclick=()=>edit(()=>delete project.symbolOverrides[b.dataset.symbolReset]));panel.querySelectorAll('[data-symbol-file]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>750000||!['image/png','image/jpeg','image/webp'].includes(file.type))return tell('750KB以下のPNG・JPEG・WebPを指定してください。');const reader=new FileReader();reader.onload=()=>edit(()=>{project.symbolOverrides[input.dataset.symbolFile]=reader.result;project.symbolMode='custom';});reader.onerror=()=>tell('画像を読み込めませんでした。');reader.readAsDataURL(file);});if(readonlyReplay)panel.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);
}
function openSupport(){if(exportBusy||pendingBattle)return tell('現在の計算・出力の完了をお待ちください。');const u=current();if(!u)return tell('リンク部隊を選択してください。');const targets=project.units.filter(t=>t.team!==u.team&&t.team!=='neutral'&&t.id!==u.id&&canTarget(project,u,t)&&viewState(t).hp>0);modal('戦闘支援 / 設定値による演出',`<p>${esc(u.name)} / 実際の迎撃率・戦術最適化は扱いません。</p><label class="field">目標<select id="support-target">${targets.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label><div class="command-tools"><button id="support-sim">攻撃Sim</button><button id="support-propose">提案</button><button id="support-execute" disabled>現在frameに実行予約</button></div><div id="support-result" class="hint">目標を選択してください。</div>`);let proposal=null;const evaluate=propose=>{const t=targets.find(t=>t.id===$('support-target').value),r=t&&supportEstimate(project,u,viewState(u),t,viewState(t));if(!r)return;proposal={target:t.id,at:frame};$('support-result').innerHTML=`<p>距離 ${fmt(r.km,2)} km / 現在位置間の飛翔時間 ${fmt(r.seconds,1)}秒</p><p>${u.type==='missile'?`一群の着弾損害 ${fmt(r.damage,1)} / ${r.message}`:'到着時間は移動速度から計算した参考値です。射撃損害は戦闘計算で確認してください。'}</p><p>${propose?'応答：選択した目標への攻撃命令を現在frameに予約できます。':'目標の移動・修理・地形防御・迎撃を含まない参考計算です。'}</p>`;$('support-execute').disabled=!!readonlyReplay;};$('support-sim').onclick=()=>evaluate(false);$('support-propose').onclick=()=>evaluate(true);$('support-target').onchange=()=>{proposal=null;$('support-execute').disabled=true;};$('support-execute').onclick=()=>{if(!proposal||frame>=project.duration)return tell('終了frame以外で予約してください。');if(u.orders.some(o=>o.at===frame))return tell('同じframeに命令があります。時刻表で編集してください。');if(edit(()=>{project.combatEnabled=true;u.orders.push({at:frame,action:u.type==='missile'?'assault':'fire',target:proposal.target,x:viewState(u).x,y:viewState(u).y,points:[],afterAction:'none',afterWait:0});})){$('modal').close();tell('時刻表に命令を追加しました。');}};}
function openVls(){if(exportBusy||pendingBattle)return tell('現在の計算・出力の完了をお待ちください。');const u=current();if(!u||project.defaults.find(t=>t.id===u.type)?.domain!=='sea')return tell('リンク部隊で艦艇を選択してください。');const rack=project.vls.find(r=>r.unitId===u.id),targets=project.units.filter(t=>t.team!==u.team&&t.team!=='neutral'&&viewState(t).hp>0);modal('武器管制 / '+u.name,`<p>セルと発射予定を保存します。性能値は追加されるミサイルの既定値を使用します。</p><label class="field">初期セル数<input id="vls-count" type="number" min="1" max="256" value="${rack?.cells.length||16}"></label><button id="vls-setup" ${rack?'disabled':''}>セルを作成（全て空）</button><div class="field-row"><button id="vls-load-all" ${rack?'':'disabled'}>未予約セルを一括装填</button><button id="vls-clear-all" ${rack?'':'disabled'}>未予約セルを空にする</button></div><div class="vls-cells">${(rack?.cells||[]).map((c,i)=>`<button data-vls-cell="${i}" class="${c.status}" ${c.status==='launched'?'disabled':''}>${i+1}<br>${{empty:'空',loaded:'装填済',launched:'予約済'}[c.status]}</button>`).join('')}</div><p class="hint">セルをクリックすると空/装填済を切り替えます。予約済のセルはプロジェクトを戻すときだけUndoできます。</p><label class="field">目標<select id="vls-target">${targets.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label><label class="field">発射数<input id="vls-fire-count" type="number" min="1" max="256" value="1"></label><button id="vls-fire">現在frameから発射予約</button>`);$('vls-setup').onclick=()=>{const count=Number($('vls-count').value);if(!Number.isInteger(count)||count<1||count>256)return tell('1〜256セルを指定してください。');if(edit(()=>project.vls.push({unitId:u.id,cells:Array.from({length:count},()=>({status:'empty',missileId:''}))})))openVls();};const fill=status=>{if(edit(()=>{const r=project.vls.find(r=>r.unitId===u.id);if(r)r.cells.forEach(c=>{if(c.status!=='launched')c.status=status;});}))openVls();};$('vls-load-all').onclick=()=>fill('loaded');$('vls-clear-all').onclick=()=>fill('empty');document.querySelectorAll('[data-vls-cell]').forEach(b=>b.onclick=()=>{if(edit(()=>{const c=project.vls.find(r=>r.unitId===u.id).cells[Number(b.dataset.vlsCell)];c.status=c.status==='empty'?'loaded':'empty';}))openVls();});$('vls-fire').onclick=()=>{const count=Number($('vls-fire-count').value),target=$('vls-target').value,r=project.vls.find(r=>r.unitId===u.id),cells=r?.cells.filter(c=>c.status==='loaded')||[],s=viewState(u);if(!target||!Number.isInteger(count)||count<1||count>256||count>cells.length||frame<u.start||s.hp<=0||frame>=project.duration)return tell('目標・装填数・艦艇状態・開始frameを確認してください。');if(edit(()=>{const m=unit(newId(),'missile',s.x,s.y,u.team,project.defaults);Object.assign(m,{name:u.name.slice(0,40)+' 発射群',start:frame,hiddenUntilStart:true,target,salvo:count,action:'assault'});project.units.push(m);project.combatEnabled=true;cells.slice(0,count).forEach(c=>{c.status='launched';c.missileId=m.id;});}))openVls();};}
function openFreeAviation(){if(exportBusy||pendingBattle)return tell('現在の計算・出力の完了をお待ちください。');const u=current();if(!u)return tell('母体となるリンク部隊を選択してください。');modal('航空機の出現予約',`<p>${esc(u.name)}の現在位置から航空機を出現させます。搭載・帰投・回収の処理はありません。</p><label class="field">兵科<select id="aviation-type">${project.defaults.filter(t=>t.domain==='air'&&t.id!=='missile').map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><label class="field">機数<input id="aviation-count" type="number" min="1" max="100" value="1"></label><button id="aviation-spawn">現在frameに配置</button>`);$('aviation-spawn').onclick=()=>{const type=$('aviation-type').value,count=Number($('aviation-count').value),s=viewState(u);if(!Number.isInteger(count)||count<1||count>100||s.hp<=0||frame<u.start)return tell('数量と母体の状態を確認してください。');if(edit(()=>{const a=unit(newId(),type,s.x,s.y,u.team,project.defaults);a.personnel=count;a.start=frame;a.hiddenUntilStart=true;project.units.push(a);})){$('modal').close();tell('航空機を追加しました。戦況編集で経路を設定してください。');}};}
$('support-action').onclick=openSupport;$('vls-action').onclick=openVls;$('aviation-action').onclick=openAviation;

function editFacility(id){if(readonlyReplay||exportBusy)return;const f=project.facilities.find(f=>f.id===id);if(!f)return;const state=facilityState(project,f,frame*project.secondsPerFrame);modal((f.name||FACILITY_TYPES[f.type])+' / 設備設定',`${f.history?`<details class="facility-provenance"><summary>歴史配置の資料・精度</summary><p>${esc(f.history.date||'')} / ${esc(f.history.note||'位置・外形は概略')}</p>${typeof f.history.source==='string'&&/^https:\/\//.test(f.history.source)?`<a href="${esc(f.history.source)}" target="_blank" rel="noopener">${esc(f.history.sourceTitle||'出典')}</a>`:''}</details>`:''}<p>現在F${frame}：${state.status} / 耐久 ${fmt(state.hp,0)} / ${state.maxHp}</p><label class="field">名称<input id="facility-name" maxlength="60" value="${esc(f.name)}"></label><label class="field">陣営<select id="edit-facility-team">${['blue','red','neutral'].map((t,i)=>`<option value="${t}" ${t===f.team?'selected':''}>${['青','赤','中立'][i]}</option>`).join('')}</select></label><label>電力系統<input id="facility-grid" maxlength="60" value="${esc(f.powerGrid)}"></label><div class="settings-fields">${[['powerOutput','発電量 / 抽象単位',0,1000000],['powerDemand','電力需要 / 抽象単位',0,1000000],['stockFuel','初期燃料在庫 / ポイント',0,1000000],['stockAmmo','初期弾薬在庫 / ポイント',0,1000000],['stockFood','初期食料在庫 / ポイント',0,1000000],['supplyRate','各資源の最大補給 / 分 / 部隊',0,1000000],['buildingHeight','建物の高さ m（保存用）',0,1000],['radiusKm','半径 / 線幅の半分 km',.01,20],['defense','追加防御力',0,10000],['damage','地雷損害（倍率適用前）',0,100000],['maxHp','最大耐久',1,1000000],['hp','初期耐久',0,1000000],['repairRate','施設の修復 / 作中秒',0,1000],['supportRate','部隊の回復HP / 作中秒',0,1000]].map(([k,n,min,max])=>`<label>${n}<input type="number" data-facility-edit="${k}" min="${min}" max="${max}" step="any" value="${f[k]}"></label>`).join('')}</div><p class="hint">耐久0で防御・地雷効果停止。自動修復は耐久が残る場合のみ。破壊後は正の耐久変化を予約すると復旧します。部隊への回復は病院・陸軍基地＝陸、海軍基地＝海、飛行場＝空の味方が範囲内にいる場合。被弾した秒・撃沈壊滅・回収済みには適用しません。重複時は最大値。人数・機数は増えません。施設への直接攻撃は未対応です。</p><button id="facility-save">基本設定を適用</button>${f.footprint==='rectangle'||f.type==='city'&&f.points.length===2?`<h3>建物・区画の寸法</h3><div class="field-row"><label>東西 m<input id="building-width" type="number" min="1" step="any" value="${Math.abs(f.points[1].x-f.points[0].x)*project.widthKm}"></label><label>南北 m<input id="building-depth" type="number" min="1" step="any" value="${Math.abs(f.points[1].y-f.points[0].y)*project.heightKm}"></label></div><button id="building-resize">北西角を固定して寸法を適用</button>`:''}<h3>設備を移動・複製</h3><p class="hint">保存済みの形状・設定・耐久時刻表を維持します。全frameの配置が変わります。東・南が正、西・北が負の値です。</p><div class="field-row"><label>東西 km<input id="facility-east" type="number" step="any" value="0"></label><label>南北 km<input id="facility-south" type="number" step="any" value="0"></label><button id="facility-move">移動</button><button id="facility-copy">複製して配置</button></div><h3>耐久変化の時刻表</h3><div class="field-row"><label>frame<input id="facility-event-at" type="number" min="0" max="10000" value="${frame}"></label><label>耐久変化（損傷は負の値）<input id="facility-event-delta" type="number" min="-1000000" max="1000000" value="-200"></label><button id="facility-event-add">予約・同時刻を更新</button></div><div class="group-plan">${f.events.map(e=>`<p>F${e.at} / ${e.delta>0?'+':''}${e.delta} <button data-facility-event-remove="${e.at}">削除</button></p>`).join('')||'状態予約はありません。'}</div><button id="facility-delete" class="danger">設備を削除</button>`);if($('building-resize'))$('building-resize').onclick=()=>{const w=Number($('building-width').value),h=Number($('building-depth').value);if(!Number.isFinite(w)||!Number.isFinite(h)||w<1||h<1)return tell('寸法を1m以上で指定してください。');if(edit(()=>{const x=Math.min(...f.points.map(v=>v.x)),y=Math.min(...f.points.map(v=>v.y));f.points=[{x,y},{x:x+w/project.widthKm,y:y+h/project.heightKm}];}))editFacility(id);};const transform=duplicate=>{const east=$('facility-east'),south=$('facility-south');if(!east.value||!south.value||!east.checkValidity()||!south.checkValidity())return tell('東西・南北の距離を指定してください。');let result=id;if(edit(()=>{let copyId='';if(duplicate){do{copyId='f-'+newId();}while(project.facilities.some(f=>f.id===copyId));}result=translateFacility(project,id,Number(east.value),Number(south.value),copyId);}))editFacility(result);};$('facility-move').onclick=()=>transform(false);$('facility-copy').onclick=()=>transform(true);$('facility-save').onclick=()=>{const inputs=[...document.querySelectorAll('[data-facility-edit]')],name=$('facility-name').value,team=$('edit-facility-team').value,grid=$('facility-grid').value;if(inputs.some(el=>!el.checkValidity()||el.value===''))return tell('設備の数値を確認してください。');if(edit(()=>{f.name=name;f.team=team;f.powerGrid=grid;inputs.forEach(el=>f[el.dataset.facilityEdit]=Number(el.value));}))editFacility(id);};$('facility-event-add').onclick=()=>{const at=Number($('facility-event-at').value),delta=Number($('facility-event-delta').value);if(edit(()=>{f.events=f.events.filter(e=>e.at!==at);f.events.push({at,delta});f.events.sort((a,b)=>a.at-b.at);}))editFacility(id);};document.querySelectorAll('[data-facility-event-remove]').forEach(b=>b.onclick=()=>{if(edit(()=>{f.events=f.events.filter(e=>e.at!==Number(b.dataset.facilityEventRemove));}))editFacility(id);});$('facility-delete').onclick=()=>{if(edit(()=>{project.facilities=project.facilities.filter(v=>v.id!==id);project.deliveries=project.deliveries.filter(d=>d.from!==id&&d.to!==id);}))$('modal').close();};}
function openFacilityList(){modal('施設一覧',`<p>設備を選択して状態と時刻表を編集します。</p><div class="group-plan">${project.facilities.map(f=>{const s=facilityState(project,f,frame*project.secondsPerFrame);return `<p><button data-open-facility="${esc(f.id)}">${esc(f.name||FACILITY_TYPES[f.type])}</button> ${s.status} / ${fmt(s.hp,0)}</p>`;}).join('')||'マップ環境の設備ツールから配置してください。'}</div>`);document.querySelectorAll('[data-open-facility]').forEach(b=>b.onclick=()=>editFacility(b.dataset.openFacility));}
function openAviation(){if(readonlyReplay||exportBusy||pendingBattle)return tell('編集可能なプロジェクトで計算完了後に操作してください。');const host=current();if(!host)return tell('搭載元の部隊をリンクしてください。');const h=project.hangars.find(h=>h.hostId===host.id),types=project.defaults.filter(t=>t.domain==='air'&&t.id!=='missile');modal('航空在庫・発艦予約 / '+host.name,`<p>保有機数を設定してから発艦を予約します。発艦時点の母体の位置へ出現。母体が壊滅・合流済みなら発艦中止です。</p><div class="field-row"><label>兵科<select id="hangar-type">${types.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><label>保有機数<input id="hangar-stock" type="number" min="0" max="1000" value="0"></label><button id="hangar-stock-save">在庫を設定</button></div><div class="group-plan">${(h?.stock||[]).map(item=>{const c=hangarCounts(h,item.type,frame,project.units.map(u=>({id:u.id,...viewState(u)})));return `<p>${esc(project.defaults.find(t=>t.id===item.type).name)}：保有${c.total} / 未予約${c.available} / 初期在庫からの予約${c.reserved} / 回収済・再出撃可能${c.recovered}</p>`;}).join('')||'在庫未設定'}</div><div class="field-row"><label>発艦frame<input id="hangar-at" type="number" min="${Math.max(frame,Math.ceil(host.start))}" max="${project.duration-1}" value="${Math.max(frame,Math.ceil(host.start))}"></label><label>機数<input id="hangar-count" type="number" min="1" max="100" value="1"></label><label>帰投開始frame（空欄＝なし）<input id="hangar-return" type="number" min="0" max="10000" placeholder="例：100"></label><button id="hangar-launch">発艦予約を追加</button></div><div class="group-plan">${(h?.sorties||[]).map(r=>`<p>F${r.at} / ${esc(project.units.find(u=>u.id===r.unitId)?.name)} / ${r.count}機 / ${esc(viewState(project.units.find(u=>u.id===r.unitId)).status)} <button data-return-sortie="${esc(r.unitId)}">帰投設定</button><button data-relaunch-sortie="${esc(r.unitId)}">回収機を再出撃</button><button data-cancel-sortie="${esc(r.unitId)}">予約と生成部隊を取り消す</button></p>`).join('')}</div><p class="hint">取り消しは過去の出現も削除します。帰投は移動中の母体を追い、50m以内で回収します。回収後は再出撃を1件予約できます。損傷を引き継ぎ、自動補充は行いません。自由配置は在庫の対象外です。</p><button id="aviation-free">在庫を使わず航空機を配置</button>`);const sync=()=>{$('hangar-stock').value=h?.stock.find(s=>s.type===$('hangar-type').value)?.count||0;};$('hangar-type').onchange=sync;sync();$('hangar-stock-save').onclick=()=>{const type=$('hangar-type').value,count=Number($('hangar-stock').value);if(edit(()=>{let rack=project.hangars.find(h=>h.hostId===host.id);if(!rack){rack={hostId:host.id,stock:[],sorties:[]};project.hangars.push(rack);}const item=rack.stock.find(s=>s.type===type);if(item)item.count=count;else rack.stock.push({type,count});}))openAviation();};$('hangar-launch').onclick=()=>{const type=$('hangar-type').value,count=Number($('hangar-count').value),at=Number($('hangar-at').value),returnAt=$('hangar-return').value===''?null:Number($('hangar-return').value),rack=project.hangars.find(h=>h.hostId===host.id);if(!rack||count>hangarCounts(rack,type,frame).available)return tell('在庫が不足しています。先に保有数を設定してください。');if(at<frame||at>=project.duration)return tell('現在frame以降、終了frameより前を指定してください。');if(edit(()=>{const s=viewState(host),a=unit(newId(),type,s.x,s.y,host.team,project.defaults);Object.assign(a,{start:at,personnel:count,hiddenUntilStart:true,launchFrom:host.id,returnAt});project.units.push(a);rack.sorties.push({unitId:a.id,type,count,at});}))openAviation();};document.querySelectorAll('[data-cancel-sortie]').forEach(b=>b.onclick=()=>{if(edit(()=>cancelSortie(project,host.id,b.dataset.cancelSortie)))openAviation();});document.querySelectorAll('[data-return-sortie]').forEach(b=>b.onclick=()=>openReturnFlight(host.id,b.dataset.returnSortie));document.querySelectorAll('[data-relaunch-sortie]').forEach(b=>b.onclick=()=>openRelaunch(host.id,b.dataset.relaunchSortie));$('aviation-free').onclick=openFreeAviation;}
const facilityExtra=document.createElement('div');facilityExtra.className='group-buttons';facilityExtra.innerHTML=Object.entries(FACILITY_TYPES).filter(([k])=>!['trench','minefield','bunker'].includes(k)).map(([k,n])=>`<button data-extra-facility="${k}">${n}</button>`).join('')+'<button id="facility-list">施設一覧・耐久</button>';$('facility-effects').closest('details').append(facilityExtra);facilityExtra.querySelectorAll('[data-extra-facility]').forEach(b=>b.onclick=()=>setTool(b.dataset.extraFacility));$('facility-list').onclick=openFacilityList;

$('facility-ops').onclick=openFacilityList;

function openReturnFlight(hostId,id){const u=project.units.find(u=>u.id===id);if(!u)return;modal('帰投時刻 / '+u.name,`<p>帰投開始後は経路・交戦より母体への帰投を優先します。母体喪失時はその場で待機します。</p><label class="field">帰投開始frame（空欄＝帰投なし）<input id="return-at" type="number" min="${u.start+1}" max="10000" value="${u.returnAt??''}"></label><button id="return-save">保存</button>`);$('return-save').onclick=()=>{const at=$('return-at').value===''?null:Number($('return-at').value);if(edit(()=>u.returnAt=at)){selected=hostId;openAviation();}};}
function openRelaunch(hostId,id){const host=project.units.find(u=>u.id===hostId),source=project.units.find(u=>u.id===id),h=project.hangars.find(h=>h.hostId===hostId),s=source&&viewState(source);if(!s?.recovered||s.recoveredCount<1)return tell('実際に帰投して回収が完了したframeで操作してください。');if(h.sorties.some(r=>r.reuseFrom===id))return tell('この隊には既に再出撃予約があります。');if(frame>=project.duration)return tell('終了frameより前に予約してください。');modal('回収機の再出撃',`<p>${esc(source.name)}：${s.recoveredCount}機を再出撃します。残存HP率${fmt(s.hp/s.maxHp*100,1)}%を引き継ぎます。余分な機体は補充しません。</p><label class="field">発艦frame<input id="relaunch-at" type="number" min="${frame}" max="${project.duration-1}" value="${frame}"></label><button id="relaunch-save">再出撃を予約</button>`);$('relaunch-save').onclick=()=>{const at=Number($('relaunch-at').value);if(!Number.isInteger(at)||at<frame||at>=project.duration)return tell('現在frame以降、終了より前を指定してください。');if(edit(()=>{const hs=viewState(host),a=unit(newId(),source.type,hs.x,hs.y,host.team,project.defaults);Object.assign(a,{name:(source.name+' 再出撃').slice(0,60),start:at,personnel:s.recoveredCount,hiddenUntilStart:true,launchFrom:hostId});project.units.push(a);h.sorties.push({unitId:a.id,type:a.type,count:a.personnel,at,reuseFrom:id});})){selected=hostId;openAviation();}};}

// MAP-23: settle in-progress polylines before any other button, including header navigation/export.
document.addEventListener('click',e=>{const button=e.target.closest?.('button');if(activeScreen!=='mapedit'||!button||button.disabled||['me-line-cancel','me-line-finish'].includes(button.id))return;if(mapEditor?.finishPending&&!mapEditor.finishPending()){e.preventDefault();e.stopImmediatePropagation();}},true);

function openUnitLogistics(id){const u=project.units.find(u=>u.id===id);if(!u||readonlyReplay||exportBusy)return;modal('兵站 / '+u.name,`<p>各資源は0〜100%。補給施設の在庫ポイントを消費して回復。兵站を設定画面で有効にすると計算します。ミサイルは対象外。移動・射撃時の消費は作中時間で固定計算します。</p><div class="settings-fields">${Object.entries(LOGISTIC_FIELDS).map(([k,n])=>`<label>${n}<input data-unit-supply="${k}" type="number" min="0" max="100" step="any" value="${u[k]??(k.startsWith('initial')?100:0)}"></label>`).join('')}</div><button id="unit-supply-save">適用</button>`);$('unit-supply-save').onclick=()=>{const inputs=[...document.querySelectorAll('[data-unit-supply]')];if(inputs.some(el=>!el.value||!el.checkValidity()))return tell('0〜100の数値で指定してください。');if(edit(()=>inputs.forEach(el=>u[el.dataset.unitSupply]=Number(el.value))))$('modal').close();};}
$('palette-search').oninput=palette;

$('delivery-ops').onclick=()=>openDeliveries();
function openDeliveries(){if(readonlyReplay||exportBusy)return;const options=project.facilities.map(f=>`<option value="${esc(f.id)}">${esc(f.name||FACILITY_TYPES[f.type])} (${f.team})</option>`).join('');modal('配送の接続・予約',`<p>同陣営の施設間で有限在庫を移送します。出発時に積み込み、指定した到着frameに加算。到着先停止時は復旧を待ちます。経路・車両・道路速度は未計算。兵站ONで動作します。</p><div class="settings-fields"><label>出発施設<select id="delivery-from">${options}</select></label><label>到着施設<select id="delivery-to">${options}</select></label><label>物資<select id="delivery-resource"><option value="fuel">燃料</option><option value="ammo">弾薬</option><option value="food">食料</option></select></label><label>数量<input id="delivery-amount" type="number" min="1" max="1000000" value="100"></label><label>出発frame<input id="delivery-depart" type="number" value="${frame}" min="0"></label><label>到着frame<input id="delivery-arrive" type="number" value="${Math.min(project.duration,frame+10)}" min="1"></label></div><button id="delivery-add">接続して予約</button><div class="group-plan">${project.deliveries.map(d=>`<p>${esc(project.facilities.find(f=>f.id===d.from)?.name)} → ${esc(project.facilities.find(f=>f.id===d.to)?.name)} / ${d.resource} ${d.amount} / F${d.depart}→F${d.arrive} <button data-delivery-delete="${d.id}">削除</button></p>`).join('')}</div>`);$('delivery-add').onclick=()=>{const d={from:$('delivery-from').value,to:$('delivery-to').value,resource:$('delivery-resource').value,amount:Number($('delivery-amount').value),depart:Number($('delivery-depart').value),arrive:Number($('delivery-arrive').value)};if(edit(()=>{let n=1;while(project.deliveries.some(d=>d.id==='delivery-'+n))n++;project.deliveries.push({id:'delivery-'+n,...d});}))openDeliveries();};document.querySelectorAll('[data-delivery-delete]').forEach(b=>b.onclick=()=>{if(edit(()=>project.deliveries=project.deliveries.filter(d=>d.id!==b.dataset.deliveryDelete)))openDeliveries();});}

function openProduction(){modal('制作設定・作戦概要',`<div class="settings-fields">${Object.entries({title:'作戦名',organization:'組織名',objective:'目的',situation:'状況',notes:'注記'}).map(([k,n])=>`<label>${n}<textarea data-briefing="${k}" maxlength="${['title','organization'].includes(k)?80:1000}">${esc(project.briefing[k])}</textarea></label>`).join('')}</div><button id="briefing-save">概要を保存</button><h3>管制画面の表示</h3><div class="field-row"><label>配色・文字の適用先<select id="production-style-scope">${Object.entries(EFFECT_SCREENS).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></label><label>配色<select id="production-palette">${Object.entries({green:'緑',amber:'琥珀',cyan:'青白'}).map(([k,n])=>`<option value="${k}" ${project.presentation.palette===k?'selected':''}>${n}</option>`).join('')}</select></label><label>文字<select id="production-font"><option value="sans">標準</option><option value="mono" ${project.presentation.font==='mono'?'selected':''}>等幅</option></select></label><label>武装表示<select id="production-layout">${Object.entries({cards:'一覧',ship:'艦内配置',vls:'VLS拡大'}).map(([k,n])=>`<option value="${k}" ${project.presentation.weaponLayout===k?'selected':''}>${n}</option>`).join('')}</select></label><button id="production-style-save">表示を保存</button></div><h3>画面演出（管制画面の表示・PNG・動画に共通）</h3><div class="field-row"><label>種類<select id="effect-type">${Object.entries(EFFECT_TYPES).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></label><label>表示先<select id="effect-screen">${Object.entries(EFFECT_SCREENS).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></label><label>色<input id="effect-color" type="color" value="#edb478"></label></div><div class="field-row"><label>開始frame<input id="effect-from" type="number" min="0" value="${frame}"></label><label>終了frame<input id="effect-to" type="number" min="0" value="${Math.min(project.duration,frame+10)}"></label><label>警報文<input id="effect-text" maxlength="80" value="ALERT / 状況更新"></label><button id="effect-add">演出を追加</button></div><p class="hint">枠の点滅は作中1秒ごと。1frameが偶数秒の場合は毎frameで同じ明るさになります。警報帯は画面下に表示し、長い文は34文字まで表示します。</p>${project.effects.map((e,i)=>`<p>F${e.from}〜${e.to} / ${esc(EFFECT_TYPES[e.type])} / ${esc(EFFECT_SCREENS[e.screen])} <button data-effect-remove="${i}">削除</button></p>`).join('')}<h3>カメラのキーフレーム</h3><label><input id="camera-enabled" type="checkbox" ${project.camera.enabled?'checked':''}>カメラを有効にする（戦況図・その動画出力）</label><div class="field-row"><label>frame<input id="camera-at" type="number" value="${frame}" min="0" max="${project.duration}"></label><label>倍率<input id="camera-zoom" type="number" min="1" max="4" step=".1" value="${zoom}"></label><label>中心 X<input id="camera-x" type="number" min="0" max="1000" value="${center.x}"></label><label>中心 Y<input id="camera-y" type="number" min="0" max="625" value="${center.y}"></label></div><label>追従<select id="camera-follow"><option value="">位置を補間</option>${project.units.map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('')}</select></label><button id="camera-add">このframeへ保存・上書き</button><div>${project.camera.keys.map((k,i)=>`<p>F${k.at} / ${k.zoom}倍 / ${esc(k.follow||'固定位置')} <button data-camera-remove="${i}">削除</button></p>`).join('')}</div><h3>カット一覧</h3><p>現在の画面・リンク部隊と区間を保存します。カットを開いて「動画・連番」から出力できます。</p><div class="field-row"><input id="cut-name" maxlength="80" value="カット ${project.cuts.length+1}" aria-label="カット名"><input id="cut-from" type="number" min="0" value="${frame}" aria-label="開始frame"><input id="cut-to" type="number" min="0" value="${project.duration}" aria-label="終了frame"><button id="cut-add">追加</button></div>${project.cuts.map((c,i)=>`<p>${esc(c.name)} / F${c.from}〜${c.to} / ${esc(SCREENS[c.screen])} <button data-cut-open="${i}">開く</button><button data-cut-remove="${i}">削除</button></p>`).join('')}`);$('production-style-scope').onchange=()=>{const v=project.screenStyles[$('production-style-scope').value]||project.presentation;$('production-palette').value=v.palette;$('production-font').value=v.font;};$('production-style-save').onclick=()=>{const config={palette:$('production-palette').value,font:$('production-font').value,weaponLayout:$('production-layout').value};const scope=$('production-style-scope').value;edit(()=>{project.presentation.weaponLayout=config.weaponLayout;if(scope==='all'){project.presentation.palette=config.palette;project.presentation.font=config.font;project.screenStyles={};}else project.screenStyles[scope]={palette:config.palette,font:config.font};});};$('effect-add').onclick=()=>{const value={from:Number($('effect-from').value),to:Number($('effect-to').value),type:$('effect-type').value,screen:$('effect-screen').value,text:$('effect-text').value,color:$('effect-color').value};if(edit(()=>{let n=1;while(project.effects.some(e=>e.id==='fx-'+n))n++;project.effects.push({id:'fx-'+n,...value});}))openProduction();};document.querySelectorAll('[data-effect-remove]').forEach(b=>b.onclick=()=>{if(edit(()=>project.effects.splice(+b.dataset.effectRemove,1)))openProduction();});$('briefing-save').onclick=()=>{const data=Object.fromEntries([...document.querySelectorAll('[data-briefing]')].map(el=>[el.dataset.briefing,el.value]));if(edit(()=>Object.assign(project.briefing,data)))openProduction();};$('camera-enabled').onchange=e=>edit(()=>project.camera.enabled=e.target.checked);$('camera-add').onclick=()=>{const k={at:Number($('camera-at').value),zoom:Number($('camera-zoom').value),x:Number($('camera-x').value),y:Number($('camera-y').value),follow:$('camera-follow').value};if(edit(()=>{project.camera.keys=project.camera.keys.filter(v=>v.at!==k.at);project.camera.keys.push(k);}))openProduction();};document.querySelectorAll('[data-camera-remove]').forEach(b=>b.onclick=()=>{if(edit(()=>project.camera.keys.splice(+b.dataset.cameraRemove,1)))openProduction();});$('cut-add').onclick=()=>{if(['settings','help','mapedit'].includes(activeScreen))return tell('戦況図または管制・作戦概要の画面からカットを追加してください。');const c={name:$('cut-name').value,from:Number($('cut-from').value),to:Number($('cut-to').value),screen:activeScreen,unitId:selected||'',mode};if(edit(()=>project.cuts.push(c)))openProduction();};document.querySelectorAll('[data-cut-open]').forEach(b=>b.onclick=()=>{const c=project.cuts[+b.dataset.cutOpen];exportCut={from:c.from,to:c.to};selected=c.unitId||selected;mode=c.mode;switchScreen(c.screen);requestFrame(c.from);$('modal').close();tell(c.name+' / 終了frame '+c.to);});document.querySelectorAll('[data-cut-remove]').forEach(b=>b.onclick=()=>{if(edit(()=>project.cuts.splice(+b.dataset.cutRemove,1)))openProduction();});}

$('restore-points').onclick=async()=>{try{const points=await listRestorePoints();modal('復元ポイント / この端末に3件',`<p>現在の作品を保存してから、過去の状態へ戻せます。自動保存とは別に保持します。</p><button id="restore-point-create">現在の作品を復元ポイントに保存</button>${points.map((p,i)=>`<p>${esc(p.title)} / ${new Date(p.at).toLocaleString()} <button data-restore-point="${i}">この状態へ復元</button></p>`).join('')}`);$('restore-point-create').onclick=async()=>{try{await saveRestorePoint(project);$('restore-points').click();tell('復元ポイントを保存しました。');}catch{tell('保存容量が不足しています。プロジェクトをファイル保存してください。');}};document.querySelectorAll('[data-restore-point]').forEach(b=>b.onclick=()=>{try{const next=validate(points[+b.dataset.restorePoint].project);checkpoint();project=next;restoreChanged();$('modal').close();tell('復元しました。元に戻すでも直前へ戻せます。');}catch(e){tell(e.message);}});}catch(e){tell('復元履歴を読み込めませんでした。'+e.message);}};

window.addEventListener('beforeunload',e=>{if(hasWeaponDrafts()){e.preventDefault();e.returnValue='';}});

document.addEventListener('invalid',e=>{e.target.setAttribute('aria-invalid','true');},true);
document.addEventListener('input',e=>{if(e.target.matches?.('input,textarea,select')&&e.target.checkValidity())e.target.removeAttribute('aria-invalid');});

$('modal-draft-discard').onclick=()=>{formDrafts.discard($('modal-title').textContent);$('modal').close();tell('このダイアログの入力下書きを破棄しました。保存済みの設定は維持されます。');};

$('palette-view').onchange=palette;
$('formations').onclick=()=>{
 let saved;try{saved=readFormationList(localStorage);}catch(e){return tell(e.message);}
 const group=project.groups.find(g=>g.id===activeGroup);
 modal('部隊編成プリセット',`<p>選択編成を現在frameに一括配置し、グループを作成します。</p><label>編成<select id="formation-choice">${[...BUILTIN_FORMATIONS,...saved].map((r,i)=>`<option value="${i}">${i<BUILTIN_FORMATIONS.length?'標準':'保存'}：${esc(r.name)} (${r.members.length}部隊)</option>`).join('')}</select></label><div class="field-row"><label>中心 東西 %<input id="formation-x" type="number" min="0" max="100" value="50"></label><label>中心 南北 %<input id="formation-y" type="number" min="0" max="100" value="50"></label><label>間隔倍率<input id="formation-scale" type="number" min="0.1" max="10" step="0.1" value="1"></label></div><p>陣営は兵科パレットの選択を使用。間隔は実距離を保持します。</p><button id="formation-place" class="primary">編成を配置</button><button id="formation-export">JSON保存</button><button id="formation-delete">保存編成を削除</button><hr><label>保存名<input id="formation-name" maxlength="60" value="${esc(group?.name||'自作編成')}"></label><p>${group?'選択グループ：'+esc(group.name):'グループ未選択：現在の全ユニット'}の初期配置・部隊設定を保存します。命令、武装、追従レーダー、搭載機、設備は含みません。保存は20件、1編成80部隊まで。</p><button id="formation-save">現在の編成を登録</button><label>編成JSONを導入<input id="formation-import" type="file" accept=".json,application/json"></label><p id="formation-result" role="status"></p>`);
 const result=message=>$('formation-result').textContent=message;
 const chosen=()=>[...BUILTIN_FORMATIONS,...saved][Number($('formation-choice').value)];
 $('formation-place').onclick=()=>{try{const out=placeFormation(project,chosen(),{x:Number($('formation-x').value)*10,y:Number($('formation-y').value)*10,scale:Number($('formation-scale').value),team:$('palette-team').value,at:frame});if(edit(()=>{project=out.project;activeGroup=out.groupId;selected=project.groups.find(g=>g.id===activeGroup).members[0];})){result('編成を配置しました。Undoでまとめて戻せます。');}}catch(e){result(e.message);}};
 $('formation-save').onclick=()=>{try{const ids=group?.members||project.units.map(u=>u.id);const r=captureFormation(project,ids,$('formation-name').value);saveFormationList(localStorage,[...saved,r]);$('modal').close();$('formations').click();}catch(e){result(e.message);}};
 $('formation-export').onclick=()=>{try{download('MFDCO-formation.json',JSON.stringify(checkFormation(chosen()),null,2),'application/json');}catch(e){result(e.message);}};
 $('formation-delete').onclick=()=>{try{const i=Number($('formation-choice').value)-BUILTIN_FORMATIONS.length;if(i<0)return result('標準編成は削除できません。');saved=saved.filter((_,j)=>i!==j);saveFormationList(localStorage,saved);$('modal').close();$('formations').click();}catch(e){result(e.message);}};
 $('formation-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('1MB以下の編成JSONを指定してください。');const r=checkFormation(JSON.parse(await file.text()));const latest=readFormationList(localStorage);saveFormationList(localStorage,[...latest,r]);$('modal').close();$('formations').click();}catch(err){result(err.message);}};
};
